// Zet de gevonden rij om naar het antwoord dat de overlegruimte verwacht:
//   { status: 'bezig' }
//   { status: 'klaar', output, forum }
// Het forum staat in maximaal zes kolommen, omdat een cel in Excel maar
// 32.767 tekens houdt. Hier plakken we die weer aan elkaar.

const rij = $input.first()?.json ?? {};

// Nog geen rij gevonden: de hoofdworkflow is nog bezig.
if (!rij.beurtId) {
  return [{ json: { status: 'bezig' } }];
}

const forumTekst = [rij.forum1, rij.forum2, rij.forum3, rij.forum4, rij.forum5, rij.forum6]
  .filter((s) => typeof s === 'string' && s.length)
  .join('');

let forum = [];
try {
  forum = forumTekst ? JSON.parse(forumTekst) : [];
} catch (e) {
  forum = [];   // liever het advies zonder overleg dan een harde fout
}

return [{
  json: {
    status: 'klaar',
    output: rij.output ?? '',
    forum,
  },
}];
